//! How Gallery lays its photos out, as Windows 11 File Explorer's Gallery
//! shows them: justified rows of thumbnails that keep each photo's aspect
//! ratio, about 160 pixels tall at Medium icons, no month headings but one
//! heading with the dates of the photos on screen, and a date scrubber at
//! the right edge with the years.
//!
//! Every picture here is generated by the test (flat colours, no people)
//! and every folder name is fictional.

use std::fs;

use gtk::prelude::*;

use super::gallery::{gallery_window, month_groups, set_modified, PicturesHome};
use crate::test_support::harness::{wait_for_frames, wait_until, TestWindow};
use crate::test_support::pictures::{jpeg_sized, png_sized};
use crate::window::gallery::ShownTile;

/// Writes a PNG of `width` by `height` pixels to `path`, modified at
/// noon of the local `date` (`YYYY-MM-DD`).
fn photo(path: &std::path::Path, width: i32, height: i32, date: &str) {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("the folder");
    }
    fs::write(path, png_sized(width, height, 0x0044_8866)).expect("the photo");
    set_modified(path, date);
}

/// The tiles on screen once Gallery has laid them out.
fn tiles(test: &TestWindow) -> Vec<ShownTile> {
    wait_until("Gallery's tiles", || !test.window.gallery_tiles().is_empty());
    wait_for_frames(&test.window, 2);
    test.window.gallery_tiles()
}

/// The tile of the photo called `name`.
fn tile<'a>(tiles: &'a [ShownTile], name: &str) -> &'a ShownTile {
    tiles
        .iter()
        .find(|tile| tile.name == name)
        .unwrap_or_else(|| panic!("{name} shows: {tiles:?}"))
}

/// The heading Gallery gives a month: its full name and year.
fn month(year: i32, month: i32) -> String {
    gtk::glib::DateTime::from_local(year, month, 1, 12, 0, 0.0)
        .and_then(|date| date.format("%B %Y"))
        .expect("a month name")
        .to_string()
}

/// Gallery lists Pictures and its subfolders newest first with no month
/// headings: the status bar counts the photos ("6 items"), and Medium
/// icons is the size it opens at.
///
/// parity: HOME-019
#[gtk::test]
fn gallery_lists_photos_newest_first_without_month_headings() {
    let home = PicturesHome::new();
    let pictures = home.pictures();
    photo(&pictures.join("a.png"), 64, 48, "2026-11-02");
    photo(&pictures.join("Trips/b.png"), 64, 48, "2026-09-10");
    photo(&pictures.join("Trips/Coast/c.png"), 64, 48, "2026-03-01");
    photo(&pictures.join("d.png"), 64, 48, "2025-12-24");
    photo(&pictures.join("Scans/e.png"), 64, 48, "2025-08-15");
    photo(&pictures.join("f.png"), 64, 48, "2025-07-04");
    let test = gallery_window(&home);

    assert_eq!(
        test.names(),
        ["a.png", "b.png", "c.png", "d.png", "e.png", "f.png"]
    );
    assert!(month_groups(&test).is_empty(), "no month headings");
    assert!(test.window.folder_pane().grouped().is_none());
    let (count, _) = test.window.status_bar().texts();
    assert_eq!(count, "6 items");
    assert_eq!(
        test.window.folder_pane().view(),
        crate::window::folder_pane::FolderView::Icons(crate::folder_view::icon_size::IconSize::MEDIUM)
    );
}

/// The thumbnails keep their photos' aspect ratios in rows that fill the
/// width, each row of one height near 160 pixels at Medium icons, with
/// even gaps between them; a narrow screenshot shows narrow.
///
/// parity: HOME-026
#[gtk::test]
fn photos_fill_justified_rows_that_keep_their_aspect_ratios() {
    let home = PicturesHome::new();
    let pictures = home.pictures();
    let shapes = [
        ("wide.png", 1600, 900),
        ("square.png", 800, 800),
        ("narrow.png", 400, 1000),
        ("panorama.png", 3000, 1000),
        ("portrait.png", 600, 800),
        ("landscape.png", 1200, 800),
        ("small.png", 300, 200),
        ("tall.png", 500, 1200),
    ];
    for (day, (name, width, height)) in shapes.iter().enumerate() {
        photo(
            &pictures.join(name),
            *width,
            *height,
            &format!("2026-05-{:02}", 28 - day),
        );
    }
    let test = gallery_window(&home);
    test.window.set_default_size(1100, 800);
    let shown = tiles(&test);
    assert_eq!(shown.len(), shapes.len(), "{shown:?}");

    for (name, width, height) in shapes {
        let tile = tile(&shown, name);
        let aspect = f64::from(width) / f64::from(height);
        let drawn = tile.width / tile.height;
        assert!(
            (drawn - aspect).abs() / aspect < 0.06,
            "{name} keeps {aspect:.2}, drawn {drawn:.2}: {tile:?}"
        );
    }
    assert!(tile(&shown, "narrow.png").width < tile(&shown, "wide.png").width / 2.0);
    wait_until("the thumbnails", || {
        test.window.gallery_tiles().iter().all(|tile| tile.thumbnail)
    });

    let view_width = test.window.gallery_content_width();
    let mut rows: Vec<Vec<&ShownTile>> = Vec::new();
    for tile in &shown {
        match rows.last_mut() {
            Some(row) if (row[0].y - tile.y).abs() < 0.5 => row.push(tile),
            _ => rows.push(vec![tile]),
        }
    }
    assert!(rows.len() >= 2, "{rows:?}");
    let gaps: Vec<f64> = rows
        .iter()
        .flat_map(|row| row.windows(2).map(|pair| pair[1].x - (pair[0].x + pair[0].width)))
        .collect();
    for gap in &gaps {
        assert!((gap - gaps[0]).abs() <= 1.0, "even gaps: {gaps:?}");
    }
    for row in &rows[..rows.len() - 1] {
        let first = row[0];
        let last = row[row.len() - 1];
        assert!(first.x.abs() <= 1.0, "rows start at the left: {row:?}");
        assert!(
            (last.x + last.width - view_width).abs() <= 1.0,
            "rows fill the width {view_width}: {row:?}"
        );
        for tile in row {
            assert!(
                (tile.height - first.height).abs() <= 1.0,
                "one height a row: {row:?}"
            );
        }
        assert!(
            (120.0..=200.0).contains(&first.height),
            "about 160 pixels tall: {row:?}"
        );
    }
    let rows_gap = rows[1][0].y - (rows[0][0].y + rows[0][0].height);
    assert!(
        (rows_gap - gaps[0]).abs() <= 1.0,
        "rows {rows_gap} apart, tiles {}",
        gaps[0]
    );

    // Larger icons, taller rows.
    test.activate("view", Some("extra-large"));
    wait_until("taller rows", || {
        test.window
            .gallery_tiles()
            .first()
            .is_some_and(|tile| tile.height > 220.0)
    });
}

/// One heading over the photos names the months of the photos on screen,
/// newest to oldest ("November 2026 – July 2025"), and follows the
/// scrolling.
///
/// parity: HOME-027
#[gtk::test]
fn the_heading_shows_the_dates_on_screen_and_follows_the_scrolling() {
    let home = PicturesHome::new();
    let pictures = home.pictures();
    let months = [
        "2026-11-03",
        "2026-08-03",
        "2026-02-03",
        "2025-11-03",
        "2025-07-03",
        "2024-12-03",
        "2024-06-03",
        "2023-03-03",
    ];
    for (index, date) in months.iter().enumerate() {
        for copy in 0..12 {
            photo(
                &pictures.join(format!("Roll {index}/frame {copy}.png")),
                640,
                480,
                date,
            );
        }
    }
    let test = gallery_window(&home);
    test.window.set_default_size(900, 640);
    let shown = tiles(&test);
    assert!(shown.len() < 96, "only some photos fit on screen");

    let first = test.window.gallery_heading().expect("the heading");
    assert!(first.starts_with(&month(2026, 11)), "{first}");
    assert!(first.contains(" – ") || first == month(2026, 11), "{first}");

    test.window.gallery_scroll_to(f64::MAX);
    wait_until("the heading to follow", || {
        test.window
            .gallery_heading()
            .is_some_and(|heading| heading.ends_with(&month(2023, 3)))
    });
    let last = test.window.gallery_heading().expect("the heading");
    assert_ne!(first, last);
    assert!(!last.starts_with(&month(2026, 11)), "{last}");
}

/// The scrubber at the right edge marks the years, says the month under
/// the pointer, and a click or a drag on it scrolls Gallery there; its
/// arrows step up and down.
///
/// parity: HOME-028
#[gtk::test]
fn the_date_scrubber_marks_years_names_months_and_jumps_there() {
    let home = PicturesHome::new();
    let pictures = home.pictures();
    let dates = [
        "2026-11-10",
        "2026-04-10",
        "2025-09-10",
        "2025-02-10",
        "2024-05-10",
    ];
    for (index, date) in dates.iter().enumerate() {
        for copy in 0..20 {
            photo(
                &pictures.join(format!("Roll {index}/frame {copy}.png")),
                640,
                480,
                date,
            );
        }
    }
    let test = gallery_window(&home);
    test.window.set_default_size(900, 640);
    tiles(&test);
    let scrubber = test.window.gallery_scrubber().expect("Gallery's scrubber");
    wait_until("the scrubber", || scrubber.is_mapped());

    let years = scrubber.year_labels();
    assert!(years.contains(&"2025".to_owned()), "{years:?}");
    assert!(years.contains(&"2024".to_owned()), "{years:?}");
    assert_eq!(scrubber.month_at(0.0).as_deref(), Some(month(2026, 11).as_str()));
    assert_eq!(scrubber.month_at(1.0).as_deref(), Some(month(2024, 5).as_str()));
    // Hovering names the month beside the scrubber; leaving hides it.
    scrubber.hover_track(Some(0.0));
    assert_eq!(test.window.gallery_hovered_month(), Some(month(2026, 11)));
    scrubber.hover_track(Some(1.0));
    assert_eq!(test.window.gallery_hovered_month(), Some(month(2024, 5)));
    scrubber.hover_track(None);
    assert_eq!(test.window.gallery_hovered_month(), None);

    scrubber.click_at(1.0);
    wait_until("the oldest photos", || {
        test.window
            .gallery_heading()
            .is_some_and(|heading| heading.ends_with(&month(2024, 5)))
    });
    scrubber.drag(1.0, 0.0);
    wait_until("the newest photos", || {
        test.window
            .gallery_heading()
            .is_some_and(|heading| heading.starts_with(&month(2026, 11)))
    });
    let top = test.window.folder_pane().scroll_position();
    scrubber.step(false);
    wait_until("a step down", || {
        test.window.folder_pane().scroll_position() > top
    });
    let lower = test.window.folder_pane().scroll_position();
    scrubber.step(true);
    wait_until("a step up", || {
        test.window.folder_pane().scroll_position() < lower
    });
}

/// A photo's tooltip says where it is, its type, its date and its size,
/// as Windows' Gallery does.
///
/// parity: HOME-029
#[gtk::test]
fn a_photos_tooltip_says_its_path_type_date_and_size() {
    let home = PicturesHome::new();
    let path = home.pictures().join("a.png");
    photo(&path, 64, 48, "2026-11-02");
    let test = gallery_window(&home);
    let tooltip = test.window.gallery_tooltip(0).expect("a tooltip");
    let lines: Vec<&str> = tooltip.lines().collect();
    assert_eq!(lines[0], format!("Path: a ({})", home.pictures().display()));
    assert_eq!(lines[1], "Item type: PNG File");
    assert!(lines[2].starts_with("Date: "), "{tooltip}");
    assert!(lines[2].contains("2026"), "{tooltip}");
    assert!(lines[3].starts_with("Size: "), "{tooltip}");
}

/// A JPEG photo keeps its JPEG look in a tile too.
///
/// parity: HOME-026
#[gtk::test]
fn a_jpeg_keeps_its_aspect_ratio_too() {
    let home = PicturesHome::new();
    let path = home.pictures().join("pier.jpg");
    fs::write(&path, jpeg_sized(300, 600, 0x0011_2233)).expect("the photo");
    let test = gallery_window(&home);
    let shown = tiles(&test);
    let pier = tile(&shown, "pier.jpg");
    assert!((pier.width / pier.height - 0.5).abs() < 0.05, "{pier:?}");
}
